/// <summary>
/// Extension class for Bank Cheque Master screen
/// </summary>
[ExtensionOf(formStr(BankChequeTable))]
public static class METBankCheque_Extension
{
}

Method.Source:
     /// <summary>
    /// Actions that will be triggered when the Bank Cheque master screen loads
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormEventHandler(formStr(BankChequeTable), FormEventType::Initialized)]
    public static void BankChequeTable_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        //Bank Account transaction Form Data Source
        FormDataSource      bankAccountTrans_ds = sender.dataSource(formDataSourceStr(BankChequeTable,BankAccountTrans));
        
        //Hide Clear Date field
        bankAccountTrans_ds.object(fieldNum(BankAccountTrans,ClearedDate)).visible(false);

    }

/// <summary>
/// OnActivated event to hide the Address of the vendor
/// </summary>
/// <param name="sender">Sender buffere</param>
/// <param name="e">Form Data Source and Event</param>
[FormEventHandler(formStr(BankChequeTable), FormEventType::Activated)]
public static void BankChequeTable_OnActivated(xFormRun sender, FormEventArgs e)
{
    //Fetch the Address Control 
    FormControl     rmtAddress = sender.design(0).controlName("Grid_RemittanceAddress");
    
    //Hide the address
    rmtAddress.visible(false);
}
